class ProxyJudge(JudgeInterface):
    """Judge using a unified OpenAI-compatible API proxy."""

    def __init__(self, model_name: str, base_url: str = None,
                 api_key: [REDACTED] = None, temperature: float = 0.0):
        from openai import OpenAI
        self.model_name = model_name
        self.temperature = temperature
        self.client = OpenAI(
            api_key=[REDACTED] or os.environ.get("OPENROUTER_API_KEY", ""),
            base_url=base_url or os.environ.get("OPENROUTER_BASE_URL", "http://47.94.22.126/v1"),
        )

    def _call(self, text: str) -> str:
        kwargs = dict(
            model=self.model_name,
            messages=[{"role": "user", "content": text}],
            max_tokens=1024,
        )
        if self.temperature is not None:
            kwargs["temperature"] = self.temperature
        resp = self.client.chat.completions.create(**kwargs)
        return resp.choices[0].message.content or ""

    def evaluate(self, prompt, response_a, response_b, swap_position=False):
        text, position = self._build_prompt(prompt, response_a, response_b, swap_position)
        return self._make_result(self._call(text), position)

    def evaluate_pointwise(self, prompt, response):
        text = self._build_pointwise_prompt(prompt, response)
        return self._make_pointwise_result(self._call(text))


